return withIdempotency(request.requestId(), "RECORD_SPLIT",
    orderedParams("raceId", raceId, "bib", bib, "checkpointCode", ..., "elapsedMillis", ..., "expectedVersion", ..., "timingId", ...),
    () -> {
        // timingId 业务幂等：先于版本校验
        Optional<SplitTimeRow> existing = repository.findSplitByTimingId(request.timingId());
        if (existing.isPresent()) {
            SplitTimeRow row = existing.get();
            if (row matches raceId,bib,checkpointCode,elapsedMillis) {
                return ServiceResult.created(toSplitTimeResponse(row)); // 重放原结果
            }
            throw new ConflictException("timingId 已用于不同参数的记录: " + ...);
        }
        RaceRow race = requireOpenRace(raceId, request.expectedVersion());
        RunnerRow runner = requireRunner(raceId, bib);
        CheckpointRow checkpoint = repository.findCheckpoint(raceId, request.checkpointCode())
            .orElseThrow(() -> new NotFoundException("检查点不存在: " + code));
        long elapsed = request.elapsedMillis();
        if (elapsed < 1 || elapsed > MAX_FINISH_TIME_MS) throw BadRequest;
        if (runner.finishTimeMs() != null && elapsed >= runner.finishTimeMs())
            throw new UnprocessableException("分段耗时不小于原始完赛耗时");
        // 相邻约束
        List<SplitTimeRow> existingSplits = repository.findSplitsForRunner(raceId, bib); // 按 seq
        // find prev (seq < checkpoint.seq) and next (seq > checkpoint.seq)
        for prev: if prev.elapsed >= elapsed → 422
        for next: if elapsed >= next.elapsed → 422
        // duplicate runner+checkpoint
        if (repository.findSplit(raceId, bib, code).isPresent()) throw Conflict("该选手在此检查点已有记录");
        bumpVersion(race, expectedVersion);
        try { repository.insertSplit(...) } catch (DuplicateKeyException ex) {
            // 并发下同 timingId 或同 runner+checkpoint
            throw new ConflictException("分段记录冲突: " + request.timingId());
        }
        SplitTimeRow row = repository.findSplitByTimingId(request.timingId()).orElseThrow();
        return ServiceResult.created(toSplitTimeResponse(row));
    });
```

