```sql
CREATE TABLE IF NOT EXISTS race_checkpoint (
    race_id VARCHAR(64) NOT NULL COMMENT '所属赛事ID',
    checkpoint_code VARCHAR(64) NOT NULL COMMENT '检查点编码，赛事内唯一',
    seq INT NOT NULL COMMENT '检查点顺序，从1开始连续递增',
    created_at BIGINT NOT NULL COMMENT '配置时间，Unix毫秒时间戳',
    CONSTRAINT pk_race_checkpoint PRIMARY KEY (race_id, checkpoint_code),
    CONSTRAINT uk_checkpoint_race_seq UNIQUE (race_id, seq),
    CONSTRAINT fk_checkpoint_race FOREIGN KEY (race_id) REFERENCES race (race_id)
);

CREATE TABLE IF NOT EXISTS split_time (
    timing_id VARCHAR(64) NOT NULL COMMENT '分段计时ID，全局唯一（业务幂等键）',
    race_id VARCHAR(64) NOT NULL COMMENT '所属赛事ID',
    bib VARCHAR(64) NOT NULL COMMENT '选手参赛号',
    checkpoint_code VARCHAR(64) NOT NULL COMMENT '检查点编码',
    elapsed_ms BIGINT NOT NULL COMMENT '分段耗时（毫秒，1~86400000），按检查点顺序严格递增且小于原始完赛耗时',
    created_at BIGINT NOT NULL COMMENT '记录时间，Unix毫秒时间戳',
    CONSTRAINT pk_split_time PRIMARY KEY (timing_id),
    CONSTRAINT uk_split_race_bib_checkpoint UNIQUE (race_id, bib, checkpoint_code),
    CONSTRAINT fk_split_runner FOREIGN KEY (race_id, bib) REFERENCES runner (race_id, bib),
    CONSTRAINT fk_split_checkpoint FOREIGN KEY (race_id, checkpoint_code) REFERENCES race_checkpoint (race_id, checkpoint_code),
    INDEX idx_split_race_bib (race_id, bib)
);

CREATE TABLE IF NOT EXISTS result_snapshot_split (
    race_id VARCHAR(64) NOT NULL COMMENT '所属快照的赛事ID',
    bib VARCHAR(64) NOT NULL COMMENT '参赛号',
    checkpoint_code VARCHAR(64) NOT NULL COMMENT '检查点编码',
    seq INT NOT NULL COMMENT '检查点顺序，从1开始',
    elapsed_ms BIGINT COMMENT '分段耗时（毫秒）；NULL表示该检查点缺失',
    CONSTRAINT pk_snapshot_split PRIMARY KEY (race_id, bib, checkpoint_code),
    CONSTRAINT fk_snapshot_split_entry FOREIGN KEY (race_id, bib) REFERENCES result_snapshot_entry (race_id, bib)
);
```

