package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 一次性配置赛事检查点请求；仅 OPEN 赛事且尚无任何分段记录时可用，配置后不可修改。
 *
 * @param checkpointCodes 检查点编码列表（1~20个），赛事内唯一，顺序从1连续递增
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record ConfigureCheckpointsRequest(
        @NotNull @Size(min = 1, max = 20) List<@NotBlank String> checkpointCodes,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

/**
 * 检查点信息：编码与顺序（从1开始连续递增）。
 *
 * @param checkpointCode 检查点编码，赛事内唯一
 * @param seq            检查点顺序，从1开始
 */
public record CheckpointInfo(String checkpointCode, int seq) {
}

package com.example.starter.race.api;

import java.util.List;

/**
 * 检查点配置响应。
 *
 * @param raceId      赛事ID
 * @param version     配置成功后的赛事版本号
 * @param checkpoints 按顺序排列的检查点列表
 */
public record CheckpointConfigResponse(
        String raceId,
        int version,
        List<CheckpointInfo> checkpoints
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 提交选手检查点通过记录请求；记录允许乱序到达，
 * 但按检查点顺序查看时耗时必须严格递增（违反返回422且不写入）。
 *
 * @param checkpointCode  检查点编码，必须属于该赛事已配置的检查点
 * @param elapsedMillis   分段耗时（毫秒，1~86400000），必须小于该选手已有原始完赛耗时
 * @param expectedVersion 客户端所见赛事版本
 * @param timingId        全局唯一分段计时ID（业务幂等键：同参重放原结果，异参409）
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record RecordSplitRequest(
        @NotBlank String checkpointCode,
        @NotNull @Positive Long elapsedMillis,
        @NotNull Integer expectedVersion,
        @NotBlank String timingId,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 单个检查点的分段明细；elapsedMillis 为 null 表示该检查点缺失（漏点）。
 *
 * @param checkpointCode 检查点编码
 * @param seq            检查点顺序，从1开始
 * @param elapsedMillis  分段耗时（毫秒）；缺失为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record SplitDetailResponse(String checkpointCode, int seq, Long elapsedMillis) {
}

package com.example.starter.race.api;

import java.util.List;

/**
 * 单个选手的分段查询响应：按检查点顺序排列，缺失检查点 elapsedMillis 为 null。
 *
 * @param raceId 赛事ID
 * @param bib    参赛号
 * @param splits 按检查点顺序（seq 升序）排列的分段明细
 */
public record RunnerSplitsResponse(
        String raceId,
        String bib,
        List<SplitDetailResponse> splits
) {
}

package com.example.starter.race.api;

import java.util.List;

/**
 * 赛事缺失检查点汇总响应；只统计已有完赛计时但未覆盖全部检查点的选手。
 *
 * @param raceId  赛事ID
 * @param runners 存在漏点的选手列表，按参赛号字典序排列
 */
public record MissingCheckpointsResponse(
        String raceId,
        List<RunnerMissingResponse> runners
