/** 分段视图：检查点配置、漏点选手集合、每选手按检查点顺序的分段明细。 */
private record SplitView(
        List<CheckpointRow> checkpoints,
        Set<String> missingCheckpointBibs,
        Map<String, List<SplitDetailResponse>> splitsByBib) {
    boolean configured() { return !checkpoints.isEmpty(); }
}

private SplitView loadSplitView(String raceId, List<RunnerRow> runners) {
    List<CheckpointRow> checkpoints = repository.findCheckpoints(raceId);
    if (checkpoints.isEmpty()) {
        return new SplitView(List.of(), Set.of(), Map.of());
    }
    List<SplitTimeRow> splits = repository.findSplitsForRace(raceId);
    Map<String, Map<String, Long>> elapsedByBib = new HashMap<>(); // bib -> code -> elapsed
    for (SplitTimeRow split : splits) {
        elapsedByBib.computeIfAbsent(split.bib(), k -> new HashMap<>())
                .put(split.checkpointCode(), split.elapsedMs());
    }
    Set<String> missing = new HashSet<>();
    Map<String, List<SplitDetailResponse>> splitsByBib = new LinkedHashMap<>();
    for (RunnerRow runner : runners) {
        Map<String, Long> elapsed = elapsedByBib.getOrDefault(runner.bib(), Map.of());
        List<SplitDetailResponse> details = new ArrayList<>(checkpoints.size());
        boolean hasMissing = false;
        for (CheckpointRow cp : checkpoints) {
            Long elapsedMs = elapsed.get(cp.checkpointCode());
            if (elapsedMs == null) hasMissing = true;
            details.add(new SplitDetailResponse(cp.checkpointCode(), cp.seq(), elapsedMs));
        }
        splitsByBib.put(runner.bib(), details);
        if (runner.finishTimeMs() != null && hasMissing) missing.add(runner.bib());
    }
    return new SplitView(checkpoints, missing, splitsByBib);
}
