                // timingId 业务幂等先于版本校验：同参重放原结果，异参409
                Optional<SplitTimeRow> existing = repository.findSplitByTimingId(request.timingId());
                if (existing.isPresent()) {
                    SplitTimeRow row = existing.get();
                    if (row.raceId().equals(raceId) && row.bib().equals(bib)
                            && row.checkpointCode().equals(request.checkpointCode())
                            && row.elapsedMs() == request.elapsedMillis()) {
                        return ServiceResult.created(ResponseMapper.toSplitTimeResponse(row));
                    }
                    throw new ConflictException("timingId 已用于不同参数的分段记录: " + request.timingId());
                }
                RaceRow race = requireOpenRace(raceId, request.expectedVersion());
                RunnerRow runner = requireRunner(raceId, bib);
                CheckpointRow checkpoint = repository.findCheckpoint(raceId, request.checkpointCode())
                        .orElseThrow(() -> new NotFoundException("检查点不存在: " + request.checkpointCode()));
                long elapsedMs = request.elapsedMillis();
                if (elapsedMs < 1 || elapsedMs > MAX_FINISH_TIME_MS) {
                    throw new BadRequestException("分段耗时毫秒数必须在 1~86400000 之间");
                }
                if (runner.finishTimeMs() != null && elapsedMs >= runner.finishTimeMs()) {
                    throw new UnprocessableException("分段耗时必须小于该选手原始完赛耗时");
                }
                if (repository.findSplit(raceId, bib, request.checkpointCode()).isPresent()) {
                    throw new ConflictException("该选手在此检查点已有分段记录: " + request.checkpointCode());
                }
                // 相邻约束：与已存在的前后相邻记录比较，按检查点顺序耗时必须严格递增
                List<SplitTimeRow> existingSplits = repository.findSplitsForRunner(raceId, bib);
                SplitTimeRow previous = null;
                SplitTimeRow next = null;
                for (SplitTimeRow split : existingSplits) {
                    if (split.seq() < checkpoint.seq()) {
                        previous = split; // 按 seq 升序，最后一个小于当前 seq 的即前邻
                    } else if (split.seq() > checkpoint.seq()) {
                        next = split;
                        break;
                    }
                }
                if (previous != null && previous.elapsedMs() >= elapsedMs) {
                    throw new UnprocessableException("分段耗时必须大于前一检查点记录: " + previous.checkpointCode());
                }
                if (next != null && elapsedMs >= next.elapsedMs()) {
                    throw new UnprocessableException("分段耗时必须小于后一检查点记录: " + next.checkpointCode());
                }
                long now = clock.millis();
                bumpVersion(race, request.expectedVersion());
                try {
                    repository.insertSplit(request.timingId(), raceId, bib, request.checkpointCode(), elapsedMs, now);
                } catch (DuplicateKeyException ex) {
                    throw new ConflictException("分段记录唯一键冲突: " + request.timingId());
                }
                SplitTimeRow row = repository.findSplitByTimingId(request.timingId()).orElseThrow();
                return ServiceResult.created(ResponseMapper.toSplitTimeResponse(row));
            });
}
```

